957	  try {
958	    text = await readFile(file, 'utf8');
959	  } catch (err) {
960	    if ((err as NodeJS.ErrnoException).code === 'ENOENT') return emptyStore();
961	    throw new BizError(`无法读取数据文件 ${file}: ${(err as Error).message}`);
962	  }
963	  let raw: unknown;
964	  try {
965	    raw = JSON.parse(text);
966	  } catch (err) {
967	    throw new BizError(
968	      `数据文件 ${file} 已损坏，不是合法 JSON：${(err as Error).message}（原文件已保留，未当作空数据覆盖）`,
969	    );
970	  }
971	  return validateStore(raw, file);
972	}
