974	// 先完整写入临时文件，再原子改名；任何失败都不触碰原文件
975	async function saveStore(file: string, store: Store): Promise<void> {
976	  let json: string;
977	  try {
978	    json = JSON.stringify(store, null, 2) + '\n';
979	  } catch (err) {
980	    throw new BizError(`序列化数据失败：${(err as Error).message}（原文件已保留）`);
981	  }
982	  const tmp = `${file}.${process.pid}.tmp`;
983	  try {
984	    await writeFile(tmp, json, {encoding: 'utf8', flag: 'wx'});
985	    await rename(tmp, file);
