996	function formatResourceIds(store: Store, ids: string[]): string {
997	  return ids
998	    .map((id) => {
999	      const r = store.resources.find((x) => x.id === id);
1000	      return r ? `${id}（${r.name}）` : id;
1001	    })
1002	    .join('、');
1003	}
