1025	function openSegmentsOf(r: ResourceRec): Array<[number, number]> {
1026	  return mergeIntervals(
1027	    r.open.map(
1028	      ([s, e]) =>
1029	        [parseDateTime(s, '开放区间开始时间'), parseDateTime(e, '开放区间结束时间')] as [number, number],
1030	    ),
1031	  );
1032	}
1033	
1034	// 从连续区间中扣除一段停用（左闭右开），返回剩余连续区间
1035	function subtractSegments(
1036	  segments: Array<[number, number]>,
1037	  cuts: Array<[number, number]>,
1038	): Array<[number, number]> {
1039	  let result = segments;
1040	  for (const [cs, ce] of mergeIntervals(cuts)) {
1041	    const next: Array<[number, number]> = [];
1042	    for (const [s, e] of result) {
1043	      if (ce <= s || e <= cs) {
1044	        next.push([s, e]);
1045	        continue;
1046	      }
1047	      if (s < cs) next.push([s, cs]);
1048	      if (ce < e) next.push([ce, e]);
1049	    }
1050	    result = next;
1051	  }
1052	  return result;
1053	}
