1075	interface CoverageGap {
1076	  id: string;
1077	  r: ResourceRec;
1078	  closures: ClosureRec[]; // 与该区间重叠的相关有效停用（按开始时间、标识排序）
1079	}
1080	
1081	// 找出实际可用时间（开放扣除有效停用）不能完整覆盖 [startMin, endMin) 的资源
1082	function findCoverageGaps(
1083	  store: Store,
1084	  ids: string[],
1085	  startMin: number,
1086	  endMin: number,
1087	): CoverageGap[] {
1088	  const gaps: CoverageGap[] = [];
1089	  for (const id of ids) {
1090	    const r = store.resources.find((x) => x.id === id)!;
1091	    if (isFullyCovered(availableSegmentsOf(store, r), startMin, endMin)) continue;
1092	    const closures = activeClosuresOf(store, id).filter((c) => {
1093	      const cs = parseDateTime(c.start, '停用开始时间');
1094	      const ce = parseDateTime(c.end, '停用结束时间');
1095	      return cs < endMin && startMin < ce;
1096	    });
1097	    gaps.push({id, r, closures});
1098	  }
1099	  return gaps;
1100	}
