1102	// 开放不足资源的统一展示：资源行 + 相关有效停用（标识与时间）
1103	function gapLines(gaps: CoverageGap[], indent: string): string[] {
1104	  const lines: string[] = [];
1105	  for (const g of gaps) {
1106	    lines.push(`${indent}- ${g.id}（${g.r.name}）`);
1107	    for (const c of g.closures) {
1108	      lines.push(`${indent}  相关有效停用: ${c.id}（${c.start} → ${c.end}）`);
1109	    }
1110	  }
1111	  return lines;
1112	}
