1130	// 与“已预约”记录求冲突：共同资源且时间重叠（左闭右开）；可排除自身
1131	function findConflicts(
1132	  store: Store,
1133	  ids: string[],
1134	  startMin: number,
1135	  endMin: number,
1136	  excludeBookingId?: string,
1137	): Conflict[] {
1138	  const wanted = new Set(ids);
1139	  const conflicts: Conflict[] = [];
1140	  for (const b of store.bookings) {
1141	    if (b.status !== 'active') continue;
1142	    if (excludeBookingId !== undefined && b.id === excludeBookingId) continue;
1143	    const bStart = parseDateTime(b.start, '预约开始时间');
1144	    const bEnd = parseDateTime(b.end, '预约结束时间');
1145	    const overlap = bStart < endMin && startMin < bEnd;
1146	    if (!overlap) continue;
1147	    const shared = b.resourceIds.filter((id) => wanted.has(id)).sort();
1148	    if (shared.length > 0) conflicts.push({booking: b, shared});
1149	  }
1150	  conflicts.sort((a, b) => a.booking.id.localeCompare(b.booking.id));
1151	  return conflicts;
1152	}
