1162	// ---------------------------------------------------------------------------
1163	// 多项预约目标的统一批次校验（无写入副作用）
1164	//
1165	// 创建系列、批量改期、安全撤销与 iCalendar 导入共用本套逻辑，不再各自重复
1166	// 整批可行性循环。校验针对“全部目标生效后”的安排，统一三类检查：
1167	//   1) 实际可用覆盖：开放区间重叠或相接合并后扣除有效停用并集，须连续覆盖目标；
1168	//   2) 批外占用：批外有效预约（已取消不占用）与目标的共同资源时间重叠；
1169	//   3) 批内冲突：本批各目标彼此之间的共同资源时间重叠。
1170	// 区间一律左闭右开，端点相接可行；仅共同资源重叠才算冲突。
1171	// 本函数只读取数据与目标，绝不修改目标、业务记录或标识计数；
1172	// 全部失败项一次性收集（批内冲突在双方各自的失败项中都出现），
1173	// 诊断的业务定位（成员时间/预约标识/UID）与报告顺序由各入口负责。
1174	// ---------------------------------------------------------------------------
1175	
1176	interface ValidationTarget {
1177	  startMin: number;
1178	  endMin: number;
1179	  resourceIds: string[]; // 已校验、按标识排序的完整目标资源集合
1180	}
1181	
1182	interface BatchTargetFailure {
1183	  index: number; // 目标数组下标（0 基）；报告顺序与业务定位由入口决定
1184	  gaps: CoverageGap[]; // 实际可用时间不能完整覆盖目标的资源及相关有效停用
1185	  external: Conflict[]; // 与批外有效预约的冲突（按预约标识排序）
1186	  internal: Array<{otherIndex: number; shared: string[]}>; // 批内冲突（双方互见）
1187	}
1188	
1189	// excludeBookingIds：本批涉及预约的标识，其当前占用不计入批外占用
1190	// （改期与撤销据此允许整批交换时段和资源；系列与导入传空集合）
1191	function validateBatchTargets(
1192	  store: Store,
1193	  targets: ReadonlyArray<ValidationTarget>,
1194	  excludeBookingIds: ReadonlySet<string> = new Set<string>(),
1195	): BatchTargetFailure[] {
1196	  const failures: BatchTargetFailure[] = [];
1197	  for (let i = 0; i < targets.length; i++) {
1198	    const t = targets[i];
1199	    const gaps = findCoverageGaps(store, t.resourceIds, t.startMin, t.endMin);
1200	    const external = findConflicts(store, t.resourceIds, t.startMin, t.endMin).filter(
1201	      (c) => !excludeBookingIds.has(c.booking.id),
1202	    );
1203	    const wanted = new Set(t.resourceIds);
1204	    const internal: BatchTargetFailure['internal'] = [];
1205	    for (let j = 0; j < targets.length; j++) {
1206	      if (j === i) continue;
1207	      const o = targets[j];
1208	      if (!(o.startMin < t.endMin && t.startMin < o.endMin)) continue;
1209	      const shared = o.resourceIds.filter((id) => wanted.has(id)).sort();
1210	      if (shared.length > 0) internal.push({otherIndex: j, shared});
1211	    }
1212	    if (gaps.length > 0 || external.length > 0 || internal.length > 0) {
1213	      failures.push({index: i, gaps, external, internal});
1214	    }
1215	  }
1216	  return failures;
1217	}
