1254	// 子命令选项解析：allowed 中列出的选项均需带值；multi 中的选项可重复
1255	function parseFlags(args: string[], allowed: string[], multi: string[] = []): ParsedFlags {
1256	  const allowedSet = new Set(allowed);
1257	  const multiSet = new Set(multi);
1258	  const values = new Map<string, string[]>();
1259	  const positionals: string[] = [];
1260	
1261	  const takeValue = (key: string, inline: string | undefined, index: number): [string, number] => {
1262	    if (inline !== undefined) return [inline, index];
1263	    const v = args[index + 1];
1264	    if (v === undefined || v.startsWith('-')) {
1265	      throw new UsageError(`选项 --${key} 缺少值`);
1266	    }
1267	    return [v, index + 1];
1268	  };
1269	
1270	  for (let i = 0; i < args.length; i++) {
1271	    const a = args[i];
1272	    if (a.startsWith('--')) {
1273	      let key: string;
1274	      let inline: string | undefined;
1275	      const eq = a.indexOf('=');
1276	      if (eq >= 0) {
1277	        key = a.slice(2, eq);
1278	        inline = a.slice(eq + 1);
1279	      } else {
1280	        key = a.slice(2);
1281	      }
1282	      if (!allowedSet.has(key)) throw new UsageError(`未知选项: --${key}`);
1283	      let v: string;
1284	      [v, i] = takeValue(key, inline, i);
1285	      if (v === '') throw new UsageError(`选项 --${key} 的值不能为空`);
1286	      if (!multiSet.has(key) && values.has(key)) {
1287	        throw new UsageError(`选项 --${key} 只能指定一次`);
1288	      }
1289	      const list = values.get(key) ?? [];
1290	      list.push(v);
1291	      values.set(key, list);
1292	    } else if (a.startsWith('-') && a !== '-') {
1293	      throw new UsageError(`未知参数: ${a}`);
1294	    } else {
1295	      positionals.push(a);
1296	    }
1297	  }
1298	  return {values, positionals};
1299	}
1300	
1301	function requireFlag(values: Map<string, string[]>, key: string): string {
1302	  const v = values.get(key)?.[0];
1303	  if (v === undefined) throw new UsageError(`缺少必需选项 --${key}`);
1304	  return v;
1305	}
