2400	// 返回裁剪到窗口内并合并后的占用区间。
2401	function flexBusySegments(
2402	  store: Store,
2403	  ids: string[],
2404	  wStart: number,
2405	  wEnd: number,
2406	): Array<[number, number]> {
2407	  const wanted = new Set(ids);
2408	  const cuts: Array<[number, number]> = [];
2409	  for (const b of store.bookings) {
2410	    if (b.status !== 'active') continue;
2411	    if (!b.resourceIds.some((id) => wanted.has(id))) continue;
2412	    const bStart = parseDateTime(b.start, '预约开始时间');
2413	    const bEnd = parseDateTime(b.end, '预约结束时间');
2414	    const a = Math.max(bStart, wStart);
2415	    const c = Math.min(bEnd, wEnd);
2416	    if (a < c) cuts.push([a, c]);
2417	  }
2418	  return mergeIntervals(cuts);
2419	}
