2782	// DTSTART/DTEND 的参数：仅允许显式的 VALUE=DATE-TIME（即默认浮动时间）；
2783	// 全天（VALUE=DATE）、时区（TZID）及其他参数一律拒绝
2784	function assertFloatingDateTimeParams(
2785	  params: string[],
2786	  label: string,
2787	  bad: (reason: string) => never,
2788	): void {
2789	  for (const p of params) {
2790	    const upper = p.toUpperCase();
2791	    if (upper === 'VALUE=DATE-TIME') continue;
2792	    if (upper === 'VALUE=DATE') bad(`${label}不支持全天事件（VALUE=DATE）`);
2793	    if (upper.startsWith('TZID=')) bad(`${label}不支持时区时间（TZID），仅接受浮动时间`);
2794	    bad(`${label}携带不支持的参数 “${p}”，仅接受浮动时间 YYYYMMDDTHHmmss`);
2795	  }
2796	}
