2801	// 解析 RRULE 值：仅支持 FREQ=WEEKLY 与 COUNT=n 两个部件（n 为 1..100000 的整数，
2802	// 含首项）；部件名大小写无关、顺序无关。空部件、重复部件、FREQ 其他取值、
2803	// INTERVAL/BYDAY/UNTIL 等任何其他部件一律拒绝。
2804	function parseWeeklyRrule(value: string, bad: (reason: string) => never): number {
2805	  const segs = value.split(';');
2806	  let freq: string | undefined;
2807	  let count: string | undefined;
2808	  for (const seg of segs) {
2809	    const eq = seg.indexOf('=');
2810	    if (eq <= 0) bad(`RRULE 部件格式非法: “${seg}”（应为 名称=值）`);
2811	    const name = seg.slice(0, eq).trim().toUpperCase();
2812	    const v = seg.slice(eq + 1).trim();
2813	    if (v === '') bad(`RRULE 部件 ${name} 的值不能为空`);
2814	    if (name === 'FREQ') {
2815	      if (freq !== undefined) bad('RRULE 的 FREQ 部件重复');
2816	      freq = v.toUpperCase();
2817	    } else if (name === 'COUNT') {
2818	      if (count !== undefined) bad('RRULE 的 COUNT 部件重复');
2819	      count = v;
2820	    } else {
2821	      bad(`不支持的 RRULE 部件 “${seg}”（仅支持 FREQ=WEEKLY 与 COUNT）`);
2822	    }
2823	  }
2824	  if (freq === undefined) bad('RRULE 缺少 FREQ 部件（仅支持 FREQ=WEEKLY）');
2825	  if (freq !== 'WEEKLY') bad(`仅支持按周重复 FREQ=WEEKLY，实际为 FREQ=${freq}`);
2826	  if (count === undefined) bad('RRULE 缺少 COUNT 部件（仅支持 FREQ=WEEKLY;COUNT=n）');
2827	  if (!/^\d+$/.test(count)) bad(`RRULE 的 COUNT 必须是整数: “${count}”`);
2828	  const n = Number(count);
2829	  if (n < 1 || n > MAX_OCCURRENCES) {
2830	    bad(`RRULE 的 COUNT 必须在 1..${MAX_OCCURRENCES} 之间（含首项）: “${count}”`);
2831	  }
2832	  return n;
2833	}
