2937	      }
2938	      const exSet = new Set<number>();
2939	      for (const ex of curExdates) {
2940	        if (!allStarts.has(ex.min)) {
2941	          bad(
2942	            `VEVENT（UID “${curUid}”）的 EXDATE ${ex.raw} 不匹配任何原开始时间` +
2943	              '（排除日期只能等于某一发生的原开始时间，时刻须一致）',
2944	          );
2945	        }
2946	        exSet.add(ex.min);
2947	      }
2948	      ev.exdates = [...exSet]
2949	        .map((m) => allStarts.get(m)!)
2950	        .sort();
2951	      for (let i = 0; i < count; i++) {
2952	        const sMin = curStart.min + i * 7 * 1440;
2953	        if (exSet.has(sMin)) continue; // 仅为未排除项生成成员
2954	        ev.occurrences.push({
2955	          startRaw: formatDateTime(sMin)!,
2956	          endRaw: formatDateTime(curEnd.min + i * 7 * 1440)!,
2957	          startMin: sMin,
2958	          endMin: curEnd.min + i * 7 * 1440,
2959	        });
2960	      }
2961	      if (ev.occurrences.length === 0) {
2962	        bad(`VEVENT（UID “${curUid}”）的全部 ${count} 个发生都被 EXDATE 排除，整批拒绝（至少保留一项）`);
2963	      }
2964	    }
2965	
2966	    events.push(ev);
2967	    inEvent = false;
2968	    curUid = undefined;
2969	    curStart = undefined;
2970	    curEnd = undefined;
2971	    curRrule = undefined;
2972	    curExdates = [];
2973	  };
2974	
2975	  for (const line of lines) {
2976	    const {name, params, value} = parseContentLine(line, bad);
