2984	      } else if (!inEvent) {
2985	        if (comp !== 'VEVENT') bad(`不支持的组件 “${value.trim()}”（仅接受 VEVENT）`);
2986	        inEvent = true;
2987	        curUid = undefined;
2988	        curStart = undefined;
2989	        curEnd = undefined;
2990	        curRrule = undefined;
2991	        curExdates = [];
2992	      } else {
2993	        bad(`事件内不允许嵌套组件 “${value.trim()}”（如 VALARM）`);
2994	      }
