124	  createBooking(df, ['R0001'], '2026-10-12T09:00', '2026-10-12T10:00', '普通预约 B0001');
125	  ok(df, ['create-series', '--resource', 'R0002', '--start', '2026-10-05T10:00', '--end', '2026-10-05T11:00', '--count', '2'], '系列 S0001'); // B0002, B0003
126	  ok(df, ['create-series', '--resource', 'R0003', '--start', '2026-10-13T10:00', '--end', '2026-10-13T11:00', '--count', '2'], '系列 S0002'); // B0004, B0005
127	  ok(df, ['add-waitlist', '--resource', 'R0001', '--start', '2026-10-14T10:00', '--end', '2026-10-14T11:00'], '候补 W0001');
128	  // W0002 与 B0004 冲突，处理时受阻继续等待；批量改期后该时段空出，但不得自动兑现
129	  ok(df, ['add-waitlist', '--resource', 'R0003', '--start', '2026-10-13T10:00', '--end', '2026-10-13T11:00'], '候补 W0002');
130	  ok(df, ['process-waitlist'], '处理候补（W0001 兑现为 B0006，W0002 等待）');
131	  createBooking(df, ['R0003'], '2026-10-16T10:00', '2026-10-16T11:00', '无关预约 B0007');
132	
133	  // 混合清单：B0001 与 B0003（S0001 成员）互换时段并整体替换资源；
134	  // B0004（S0002 成员）改时间并整体替换为多资源；B0006（候补兑现）为未变化项
135	  const manifest = writeManifest(dir, 'mixed.json', [
