import {open, readFile: ..., unlink, ...} from 'node:fs/promises';
import {resolve} from 'node:path';
import {randomUUID} from 'node:crypto';

const LOCK_TIMEOUT_MS = 5000;
const LOCK_RETRY_MS = 40;

interface HeldLock { path: string; token: string }
let heldLock: HeldLock | null = null;

function lockPathFor(dataFile: string): string {
  return resolve(dataFile) + '.lock';
}

async function acquireDataLock(dataFile: string): Promise<void> {
  const lockPath = lockPathFor(dataFile);
  if (heldLock && heldLock.path === lockPath) return;
  const token = `${process.pid}-${randomUUID()}`;
  const content = JSON.stringify({pid: process.pid, token, dataFile: resolve(dataFile), acquiredAt: new Date().toISOString()}) + '\n';
  const deadline = Date.now() + LOCK_TIMEOUT_MS;
