```ts
function runCliAsync(dataFile, args, opts?: {cwd?: string; env?: NodeJS.ProcessEnv}): Promise<CliResult> {
  return new Promise((resolveP, reject) => {
    const cp = spawn(process.execPath, [APP, '--data', dataFile, ...args], {encoding: 'utf8', cwd: opts?.cwd, env: {...process.env, ...opts?.env}});
    let stdout = '', stderr = '';
    cp.stdout.on('data', d => stdout += d);
    cp.stderr.on('data', d => stderr += d);
    cp.on('error', reject);
    cp.on('close', code => resolveP({status: code ?? -1, stdout, stderr}));
  });
}
