```ts
interface HeldLock { path: string; token: string }
let heldLock: HeldLock | null = null;

function sleep(ms: number): Promise<void> { return new Promise((r) => setTimeout(r, ms)); }

async function acquireDataLock(dataFile: string): Promise<void> {
  const lockPath = lockPathFor(dataFile);
  if (heldLock !== null) {
    if (heldLock.path === lockPath) return;
    throw new Error('内部错误：一个进程只保护一个数据文件'); // 不可达
  }
  const token = `${process.pid}-${randomUUID()}`;
  const content = JSON.stringify({
    pid: process.pid,
    token,
    dataFile: resolve(dataFile),
    acquiredAt: new Date().toISOString(),
  }) + '\n';
  const deadline = Date.now() + LOCK_WAIT_TIMEOUT_MS;
  for (;;) {
    try {
      const handle = await open(lockPath, 'wx');
      try {
        await handle.writeFile(content);
      } finally {
        await handle.close();
      }
      heldLock = {path: lockPath, token};
      break;
    } catch (err) {
      const code = (err as NodeJS.ErrnoException).code;
      if (code === 'EEXIST') {
        if (Date.now() >= deadline) {
          throw new BizError(
            `数据文件 ${dataFile} 正被其他进程占用（等待 ${LOCK_WAIT_TIMEOUT_MS / 1000} 秒仍未取得写入保护），` +
              '本次未做任何改动；请稍后重试。若确认原写入进程已退出，可使用 recover-lock 解除残留保护。',
          );
        }
        await sleep(LOCK_RETRY_INTERVAL_MS);
        continue;
      }
      throw new BizError(`无法取得数据文件 ${dataFile} 的写入保护：${(err as Error).message}（本次未做任何改动）`);
    }
  }
  // 测试钩子：取得保护后停留指定毫秒，用于可重复地制造多进程竞争与异常终止现场
  const holdMs = Number(process.env.SHIFTBOOK_LOCK_HOLD_MS ?? '0');
  if (Number.isFinite(holdMs) && holdMs > 0) await sleep(holdMs);
}
```

