```ts
async function cmdRecoverLock(args: string[]): Promise<void> {
  const {values, positionals} = parseFlags(args, []);
  if (values.size > 0) throw new UsageError(`recover-lock 不接受选项: ...`);
  if (positionals.length > 0) throw new UsageError(`recover-lock 不接受位置参数: ...`);

  const file = activeDataFile;
  const lockPath = lockPathFor(file);
  let text: string;
  try {
    text = await readFile(lockPath, 'utf8');
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === 'ENOENT') {
      console.log(`数据文件 ${file} 当前没有写入保护，无需恢复。`);
      return;
    }
    throw new BizError(`无法读取写入保护文件 ${lockPath}: ${(err as Error).message}`);
  }

  let info: {pid?: unknown; token?: unknown; acquiredAt?: unknown};
  try {
    info = JSON.parse(text) as typeof info;
  } catch {
    throw new BizError(`写入保护文件 ${lockPath} 内容无法辨认，无法确认原写入进程，拒绝解除（请人工检查该文件）`);
  }
  const pid = info.pid;
  if (typeof pid !== 'number' || !Number.isInteger(pid) || pid <= 0) {
    throw new BizError(`写入保护文件 ${lockPath} 缺少有效的持有者进程号，无法确认原写入进程，拒绝解除（请人工检查该文件）`);
  }
  if (processAlive(pid)) {
    throw new BizError(
      `数据文件 ${file} 的写入保护由进程 ${pid} 持有且该进程仍存活，拒绝解除` +
        '（不按保护存在时长抢占）；请等待其结束后重试',
    );
  }
  // 原写入进程已退出：解除前重新核对保护内容未变，避免误删他人新取得的保护
  let again: string;
  try {
    again = await readFile(lockPath, 'utf8');
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === 'ENOENT') {
      console.log(`数据文件 ${file} 的写入保护已被解除，无需恢复。`);
      return;
    }
    throw new BizError(`无法读取写入保护文件 ${lockPath}: ${(err as Error).message}`);
  }
  if (again !== text) {
    throw new BizError(`写入保护在检查期间已被更换，无法确认仍为残留保护，拒绝解除；请稍后重试`);
  }
  try {
    await unlink(lockPath);
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === 'ENOENT') {
      console.log(`数据文件 ${file} 的写入保护已被解除，无需恢复。`);
      return;
    }
    throw new BizError(`解除写入保护失败：${(err as Error).message}`);
  }
  console.log(
    `已解除数据文件 ${file} 的残留写入保护（原写入进程 ${pid} 已退出）；` +
      '未重放任何命令，业务数据与标识计数不变。',
  );
}
